fn convert_string_to_bool(csharp_test: &String, original_test_node: &Expr) -> String {
    match &original_test_node {
        Expr::Bin(_) | Expr::Bin(_) => {
            return csharp_test.clone();
        }
        _ => {}
    }
    match original_test_node {
        Expr::Unary(unary) => {
            if (unary.operator == "!") {
                return csharp_test.clone();
            }
        }
        _ => {}
    }
    format!("MinimactHelpers.ToBool({})", csharp_test)
}

