pub fn generate_csharp_statement(node: &Statement) -> String {
    match node {
        Stmt::Expr(expr_stmt) => {
            {
                format!("{};", Self::generate_csharp_expression(&expr_stmt.expression, false))
            }
        }
        Stmt::Return(ret) => {
            {
                if ret.argument.is_none() {
                    "return;".into()
                } else {
                    format!("return {};", Self::generate_csharp_expression(ret.argument.as_ref().unwrap(), false))
                }
            }
        }
        Stmt::Throw(throw_stmt) => {
            {
                format!("throw {};", Self::generate_csharp_expression(&throw_stmt.argument, false))
            }
        }
        Decl::Var(var_decl) => {
            {
                let declarations = var_decl.declarations.iter().map(|d| {
                    if &d.id {
                        let name = &id.name;
                        let value = if &d.init {
                            generate_csharp_expression(init, false);
                        } else {
                            "null".into();
                        };
                        format("var {} = {};", name, value)
                    } else {
                        "".into()
                    }
                }).collect();
                declarations.join(" ")
            }
        }
        Stmt::If(if_stmt) => {
            {
                let mut test = Self::generate_csharp_expression(&if_stmt.test, false);
                test = Self::convert_string_to_bool(&test, &if_stmt.test);
                let mut result = format!("if ({}) {{\n", test);
                match &if_stmt.consequent {
                    Stmt::Block(block) => {
                        for stmt in &block.body {
                            result.push_str("    ");
                            result.push_str(&Self::generate_csharp_statement(stmt));
                            result.push_str("\n");
                        }
                    }
                    _ => {
                        result.push_str("    ");
                        result.push_str(&Self::generate_csharp_statement(&if_stmt.consequent));
                        result.push_str("\n")
                    }
                }
                result.push_str("}");
                match &if_stmt.alternate {
                    Some(alternate) => {
                        result.push_str(" else {\n");
                        match alternate {
                            Stmt::Block(block) => {
                                for stmt in &block.body {
                                    result.push_str("    ");
                                    result.push_str(&Self::generate_csharp_statement(stmt));
                                    result.push_str("\n");
                                }
                            }
                            _ => {
                                match alternate {
                                    Stmt::If(_) => {
                                        result.push_str("    ");
                                        result.push_str(&Self::generate_csharp_statement(alternate));
                                        result.push_str("\n")
                                    }
                                    _ => {
                                        result.push_str("    ");
                                        result.push_str(&Self::generate_csharp_statement(alternate));
                                        result.push_str("\n")
                                    }
                                }
                            }
                        }
                        result.push_str("}")
                    }
                    _ => {}
                }
                result
            }
        }
        Stmt::Try(try_stmt) => {
            {
                let mut result = "try {\n".to_string();
                match &try_stmt.block {
                    Some(block) => {
                        for stmt in &block.body {
                            result.push_str("    ");
                            result.push_str(&Self::generate_csharp_statement(stmt));
                            result.push_str("\n");
                        }
                    }
                    _ => {}
                }
                result.push_str("}");
                match &try_stmt.handler {
                    Some(handler) => {
                        let catch_param = if &handler.param {
                            match param {
                                Pat::Ident(id) => {
                                    id.sym.to_string().clone()
                                }
                                _ => {
                                    "ex".into()
                                }
                            }
                        } else {
                            "ex".into()
                        };
                        result.push_str(&format!(" catch (Exception {}) {{\n", catch_param));
                        for stmt in &handler.body.body {
                            result.push_str("    ");
                            result.push_str(&Self::generate_csharp_statement(stmt));
                            result.push_str("\n");
                        }
                        result.push_str("}")
                    }
                    _ => {}
                }
                match &try_stmt.finalizer {
                    Some(finalizer) => {
                        result.push_str(" finally {\n");
                        for stmt in &finalizer.body {
                            result.push_str("    ");
                            result.push_str(&Self::generate_csharp_statement(stmt));
                            result.push_str("\n");
                        }
                        result.push_str("}")
                    }
                    _ => {}
                }
                result
            }
        }
        _ => {
            {
                format!("{};", "/* unknown statement */")
            }
        }
    }
}

pub fn generate_csharp_expression(node: &Expr, in_interpolation: bool) -> String {
    match node {
        Lit::Str(lit) => {
            {
                generate_string_literal(lit, in_interpolation)
            }
        }
        Lit::Num(lit) => {
            {
                generate_numeric_literal(lit)
            }
        }
        Lit::Bool(lit) => {
            {
                generate_boolean_literal(lit)
            }
        }
        Lit::Null(lit) => {
            {
                generate_null_literal(lit)
            }
        }
        Expr::Ident(ident) => {
            {
                unsafe {
                    let comp_ptr = CURRENT_COMPONENT.unwrap_or(std::ptr::null());
                    let comp_ref = if !comp_ptr.is_null() {
                        Some(&*comp_ptr)
                    } else {
                        None
                    };
                    generate_identifier(ident, comp_ref);
                }
            }
        }
        Expr::Assign(assign) => {
            {
                generate_assignment_expression(assign, generate_csharp_expression, in_interpolation)
            }
        }
        Expr::Await(await_expr) => {
            {
                format!("await {}", Self::generate_csharp_expression(&await_expr.argument, in_interpolation))
            }
        }
        Expr::TSAsExpression(as_expr) => {
            {
                Self::generate_csharp_expression(&as_expr.expression, in_interpolation)
            }
        }
        Expr::TSTypeAssertion(type_assert) => {
            {
                Self::generate_csharp_expression(&type_assert.expression, in_interpolation)
            }
        }
        Expr::OptionalMemberExpression(opt_mem) => {
            {
                generate_optional_member_expression(opt_mem, generate_csharp_expression, in_interpolation)
            }
        }
        Expr::Member(mem) => {
            {
                generate_member_expression(mem, generate_csharp_expression, in_interpolation)
            }
        }
        Expr::Array(arr) => {
            {
                generate_array_expression(arr, generate_csharp_expression)
            }
        }
        Expr::Unary(unary) => {
            {
                generate_unary_expression(unary, generate_csharp_expression, in_interpolation)
            }
        }
        Expr::Bin(bin) => {
            {
                generate_binary_expression(bin, generate_csharp_expression)
            }
        }
        Expr::Bin(logical) => {
            {
                generate_logical_expression(logical, generate_csharp_expression)
            }
        }
        Expr::Cond(cond) => {
            {
                generate_conditional_expression(cond, generate_csharp_expression)
            }
        }
        Expr::Call(call) => {
            {
                unsafe {
                    let comp_ptr = CURRENT_COMPONENT.unwrap_or(std::ptr::null());
                    let comp_ref = if !comp_ptr.is_null() {
                        Some(&*comp_ptr)
                    } else {
                        None
                    };
                    generate_call_expression(call, generate_csharp_expression, generate_csharp_statement, comp_ref);
                }
            }
        }
        Expr::OptionalCallExpression(opt_call) => {
            {
                unsafe {
                    let comp_ptr = CURRENT_COMPONENT.unwrap_or(std::ptr::null());
                    let comp_ref = if !comp_ptr.is_null() {
                        Some(&*comp_ptr)
                    } else {
                        None
                    };
                    generate_optional_call_expression(opt_call, generate_csharp_expression, generate_csharp_statement, comp_ref);
                }
            }
        }
        Expr::Tpl(template) => {
            {
                generate_template_literal(template, generate_csharp_expression)
            }
        }
        Expr::New(new_expr) => {
            {
                generate_new_expression(new_expr, generate_csharp_expression)
            }
        }
        Expr::Object(obj) => {
            {
                generate_object_expression(obj, generate_csharp_expression)
            }
        }
        Expr::Arrow(arrow) => {
            {
                generate_function_expression(&Expression::ArrowFunctionExpression(Box::new(Expr::Arrow(arrow.clone()))), generate_csharp_expression, generate_csharp_statement)
            }
        }
        Expr::Fn(func) => {
            {
                generate_function_expression(&Expression::FunctionExpression(Box::new(Expr::Fn(func.clone()))), generate_csharp_expression, generate_csharp_statement)
            }
        }
        _ => {
            {
                let node_path = get_path_from_node(node);
                format!("new VNull(\"{}\")", node_path)
            }
        }
    }
}

pub fn generate_attribute_value(value: &JSXAttributeValue) -> String {
    match value {
        Lit::Str(lit) => {
            {
                format!("\"{}\"", escape_csharp_string(&String::from_utf8_lossy(lit.value.as_bytes())))
            }
        }
        JSXElementChild::JSXExprContainer(container) => {
            {
                Self::generate_csharp_expression(&*container.expr, false)
            }
        }
        _ => {
            "\"\"".into()
        }
    }
}

pub fn generate_hybrid_expression(expr: &Expr, component: &Component, deps: &Dependencies, indent: i32) -> String {
    format!("new VText({})", Self::generate_csharp_expression(expr, false))
}

pub fn set_current_component(component: &Component) {
    unsafe {
        CURRENT_COMPONENT = Some(component);
    }
}

